cases.new:
for index in table.indexes() {
    if index.is_unique() {
        out.refusals.push(Refusal::SoleWriterNotEstablished {
            table: table.name().to_owned(),
            index: index.name().to_owned(),
        });
    }
    out.steps.push(Step::BuildIndex {
        table: table.id(),
        index: index.id(),
        name: index.name().to_owned(),
    });
}
